(() => {
 const req = process.mainModule.require.bind(process.mainModule);
 const path = req('node:path');
 global.__ltReq = name => req(path.join(process.cwd(),'dist/main',name));
 const service=__ltReq('core/system/provider-quota-service.js').getProviderQuotaService();
 global.__lt = {mode:'baseline', requests:[], notifications:[], quotaCalls:0};
 const original=global.fetch;
 global.__ltOriginalFetch=original;
 global.fetch=async (input,init) => {
   const u=new URL(typeof input==='string'?input:input.url);
   const quota=u.hostname==='platform.xiaomimimo.com' && u.pathname.startsWith('/api/v1/tokenPlan/');
   const account=u.hostname==='account.xiaomi.com';
   const relevant=quota || account || u.hostname.endsWith('.xiaomimimo.com');
   let omitted=false;
   if (quota) __lt.quotaCalls++;
   if ((quota && (__lt.mode==='reject' || (__lt.mode==='renew' && __lt.quotaCalls<=2))) || (account && __lt.mode==='reject')) {
     const headers=new Headers(init?.headers);headers.delete('Cookie');
     init={...init,headers};omitted=true;
   }
   const response=await original(input,init);
   if(relevant) __lt.requests.push({at:new Date().toISOString(),phase:__lt.mode,host:u.hostname,path:u.pathname,status:response.status,cookieOmitted:omitted,hasLocation:!!response.headers.get('location'),setCookieCount:response.headers.getSetCookie?.().length??0});
   return response;
 };
 const notification=__ltReq('notifications/notification-service.js').getNotificationService();
 notification.subscribe(record=>{if(record.kind==='quota-reauth') __lt.notifications.push({kind:record.kind,title:record.title,delivery:record.delivery,createdAt:record.createdAt})});
 global.__ltProbe=service.probes.get('opencode');
 const chain=[];let p=__ltProbe;
 while(p){chain.push(p.constructor.name);p=p.inner??p.native??p.wrapped??p.delegate;}
 return {profile:req('electron').app.getPath('userData'),chain,desktopSupported:req('electron').Notification.isSupported(),savedSessionAvailable:__ltReq('core/system/provider-quota/mimo-saved-session-store.js').getMimoSavedSessionStore().has('legacy')};
})()

(() => {
 const probe=__ltProbe.inner.native;
 const req=process.mainModule.require.bind(process.mainModule);
 const fs=req('fs'),path=req('path'),crypto=req('crypto');
 const digest=p=>crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
 const source=path.join(req('os').homedir(),'Library/Application Support/harness/mimo-usage-sessions/legacy.bin');
 const isolated=path.join(req('electron').app.getPath('userData'),'mimo-usage-sessions/legacy.bin');
 const sourceBefore=digest(source),isolatedBefore=digest(isolated);
 const originalSave=probe.reader.saveRenewed.bind(probe.reader);
 probe.reader.saveRenewed=(...args)=>{
   const result=originalSave(...args);
   __lt.persistence={sourceUnchanged:digest(source)===sourceBefore,isolatedBlobChanged:digest(isolated)!==isolatedBefore,rotatedSsoPairs:args[1]?.length??0};
   return result;
 };
 // Separate the failed-SSO and saved-SSO cases without a 30-minute wait.
 // Only the renewer's attempt timer is reset by making a fresh renewer;
 // cached quota, notification history and all production I/O remain live.
 probe.renewer=new (__ltReq('core/system/provider-quota/mimo-console-session-renewer.js').MimoConsoleSessionRenewer)();
 __lt.mode='renew';__lt.quotaCalls=0;
 return {mode:__lt.mode,renewalAttemptBudgetResetForIndependentCase:true};
})()

(async()=>{
 await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 const original=await window.electronAPI.getSettings();
 window.__ltOriginalModel=original.data.defaultModelByProvider;
 const changed=await window.electronAPI.updateSettings({defaultModelByProvider:{...window.__ltOriginalModel,opencode:'xiaomi-token-plan-ams/mimo-v2.6-pro'}});
 const refreshed=await window.electronAPI.quotaRefresh('opencode');
 if(!changed.success || !refreshed.success || !refreshed.data?.ok) throw new Error('Initial live quota unavailable');
 document.querySelector('[data-testid="quota-toggle"]').click();
 await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 return {snapshot:refreshed.data,strip:document.querySelector('[data-testid="quota-strip"]').textContent,row:document.querySelector('[data-testid="quota-provider-opencode"]').textContent};
})()

(async()=>{
 const before=(await window.electronAPI.quotaGetProvider('opencode')).data;
 document.querySelector('[data-testid="quota-refresh-opencode"]').click();
 await new Promise(r=>setTimeout(r,8000));
 await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
 const after=(await window.electronAPI.quotaGetProvider('opencode')).data;
 return {before,after,strip:document.querySelector('[data-testid="quota-strip"]').textContent,row:document.querySelector('[data-testid="quota-provider-opencode"]').textContent,reauthVisible:!!document.querySelector('[data-testid="quota-reauth-opencode"]'),barCount:document.querySelectorAll('[data-testid="quota-provider-opencode"] .bar').length};
})()

(async()=>{
 const before=(await window.electronAPI.quotaGetProvider('opencode')).data;
 document.querySelector('[data-testid="quota-refresh-opencode"]').click();
 let row='';
 for(let i=0;i<28;i++) {
   await new Promise(r=>setTimeout(r,5000));
   await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));
   row=document.querySelector('[data-testid="quota-provider-opencode"]').textContent;
   if(/updated [1-9]\d*m ago/.test(row) && document.querySelector('[data-testid="quota-reauth-opencode"]')) break;
 }
 const after=(await window.electronAPI.quotaGetProvider('opencode')).data;
 return {before,after,ageMs:Date.now()-after.takenAt,row,reauthVisible:!!document.querySelector('[data-testid="quota-reauth-opencode"]'),barCount:document.querySelectorAll('[data-testid="quota-provider-opencode"] .bar').length};
})()

const fs = require('node:fs');
const WebSocket = require('ws');
(async () => {
  const port = process.argv[2] === 'main' ? 9823 : 9822;
  let page;
  for(let attempt=0;attempt<60;attempt++){
    const pages = await (await fetch(`http://127.0.0.1:${port}/json/list`)).json();
    page = pages.find(p => port === 9823 || (p.type === 'page' && p.url.includes('4579')));
    if(page) break;
    await new Promise(r=>setTimeout(r,500));
  }
  if (!page) throw new Error('Expected isolated app target absent');
  const ws = new WebSocket(page.webSocketDebuggerUrl);
  await new Promise((resolve,reject)=>{ws.once('open',resolve);ws.once('error',reject)});
  let next=0; const pending=new Map();
  ws.on('message',raw=>{const m=JSON.parse(raw); const p=pending.get(m.id);if(p){pending.delete(m.id);m.error?p.reject(new Error(m.error.message)):p.resolve(m.result)}});
  const send=(method,params={})=>new Promise((resolve,reject)=>{const id=++next;pending.set(id,{resolve,reject});ws.send(JSON.stringify({id,method,params}))});
  const timer=setTimeout(()=>{ws.terminate();process.exitCode=1;console.error('CDP operation timed out')},180000);
  try {
    let focus;
    if(port===9822){
      await send('Emulation.setFocusEmulationEnabled',{enabled:true});
      try{await send('Emulation.setPageVisibilityOverride',{visibility:'visible'})}catch{}
      const f=await send('Runtime.evaluate',{expression:'({hidden:document.hidden,visibility:document.visibilityState})',returnByValue:true});
      focus=f.result.value;
      if(focus.hidden || focus.visibility!=='visible') throw new Error('Focus emulation failed');
    }
    const result=await send('Runtime.evaluate',{expression:fs.readFileSync(process.argv[3],'utf8'),awaitPromise:true,returnByValue:true});
    if(result.exceptionDetails) throw new Error('Evaluation failed: '+String(result.exceptionDetails.exception?.description??result.exceptionDetails.text).slice(0,250));
    console.log(JSON.stringify({at:new Date().toISOString(),focus,result:result.result.value},null,2));
  } finally {clearTimeout(timer);ws.close()}
})().catch(e=>{console.error(e.message);process.exitCode=1});
